  'Confirm with a passkey': 'Confirmer avec une passkey',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Confirmé. Crée maintenant la nouvelle passkey ; ton navigateur te demandera où la garder.',
  'Copy link': 'Copier le lien',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Crée sur cet appareil une passkey pour le profil « {0} ». C’est avec elle que tu te connectes ici désormais.',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Chacune te connecte à ce profil depuis l’appareil ou le gestionnaire de mots de passe qui la garde. Touches-en une pour la renommer ou la retirer.',
  'Enter the code from your other device.': 'Saisis le code de ton autre appareil.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Pour cet appareil, une clé de sécurité, un gestionnaire de mots de passe, ou ton téléphone via le code QR du navigateur lui-même. Confirme d’abord que c’est bien toi.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Elle ne pourra plus se connecter à ce profil. Un appareil déjà connecté avec elle le reste. S’il a été perdu, utilise « Se déconnecter partout ».',
  'It is your only way in, so it cannot be removed until there is another.': 'C’est ton seul moyen d’entrer, elle ne peut donc pas être retirée tant qu’il n’y en a pas d’autre.',
  'Last used {0}': 'Utilisée pour la dernière fois le {0}',
