  'Deload routine': 'Routine de décharge',
  'Its workouts do not count toward progression. They still show in history and statistics.': 'Ses séances ne comptent pas pour la progression. Elles restent dans l’historique et les statistiques.',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': 'Une routine de décharge démarre avec les valeurs définies ici, la progression ci-dessus ne s’y applique donc pas.',
  'Linear progression': 'Progression linéaire',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': 'Double progression',
  'Add time': 'Ajouter du temps',
  'Targets stay where you set them.': 'Les objectifs restent tels que tu les as définis.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Réussis toutes les répétitions de toutes les séries et le poids augmente. Des échecs répétés déclenchent une décharge.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Deux séries normales puis une dernière menée à l’échec. Dépasse l’objectif sur celle-ci et le poids augmente (le double si tu doubles les répétitions). Un échec ramène de 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Progresse dans une fourchette de répétitions au même poids. Atteins le haut de la fourchette sur toutes les séries et le poids augmente, les répétitions repartent du bas.',
  'Hold every set for the full duration and the target goes up.': 'Tiens chaque série pendant toute la durée et l’objectif augmente.',
  'Nothing logged yet, so this session sets the baseline.': 'Rien d’enregistré pour l’instant, donc cette séance fixe la référence.',
  'Held every set for the full time. Target goes up by {0}s.': 'Toutes les séries tenues jusqu’au bout. Objectif +{0} s.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0} séances trop courtes d’affilée. Redescends à {1} s et remonte petit à petit.',
  'Came up short last time. Same target again.': 'Un peu juste la dernière fois. Même objectif.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Haut de la fourchette sur toutes les séries. {0} {1} de plus, retour à {2} répétitions.',
  'Stuck for {0} sessions. Deload to {1} {2}.': 'Bloqué depuis {0} séances. Décharge à {1} {2}.',
  'Same weight, aim for {0} reps this time.': 'Même poids, vise {0} répétitions cette fois.',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'Dernière série à {0} répétitions, le double de l’objectif ! Fais un saut double de {1} {2}.',
  'Every rep last time. {0} {1} more.': 'Toutes les répétitions la dernière fois. {0} {1} de plus.',
  'Every rep last time. {0} {1} less help.': 'Toutes les répétitions la dernière fois. {0} {1} d’aide en moins.',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'Haut de la fourchette de répétitions à chaque série. {0} {1} d’aide en moins, retour à {2} répétitions.',
  'Missed reps. {0} {1} of help while you build back up.': 'Répétitions manquées. {0} {1} d’aide le temps de remonter.',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': '{0} séances au point mort. Retour à {1} {2} d’aide, puis on remonte.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'Répétitions manquées {0} séances de suite. Retour à {1} {2} et on remonte.',
  'Missed reps. Reset to {0} {1} and work back up.': 'Répétitions manquées. Retour à {0} {1} et on remonte.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'Répétitions manquées la dernière fois. Même poids encore ({0} sur {1} restants).',
