  'Week by week': 'Semaine par semaine',
  'Where the sets land': 'Où tombent les séries',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'La plupart des séries de travail se placent près de l’échec, pas à l’échec. La moitié tout en bas et la moitié tout en haut, ça donne quand même une moyenne qui a l’air saine.',
  'Average effort per workout': 'Effort moyen par séance',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': 'Un point plus plein veut dire moins de réserve. Le même poids à un {0} plus bas, c’est un progrès que la ligne seule ne montre pas.',

