  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Un tirage pour chaque poussée, pour garder les épaules équilibrées.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Une rotation sur deux jours répartie sur trois séances par semaine, construite autour du matériel que tu as indiqué. Les polyarticulaires d’abord, un tirage pour chaque poussée, et assez de recoupement entre les jours pour que rien ne reste deux semaines sans être travaillé.',
  'Based on the training already in this demo profile.': 'D’après l’entraînement déjà présent dans ce profil de démo.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Le poids de corps stagne depuis quatre semaines alors que l’objectif est de prendre du poids. C’est un problème de cuisine, pas d’entraînement. Ce n’est pas le plan qui bloque.',
  'Demo': 'Démo',
  'Demo data reset': 'Données de démo réinitialisées',
  'Direct arm work, since you asked for it.': 'Du travail direct des bras, puisque tu l’as demandé.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Toutes les séries principales de cet exercice ont été à RPE 9,5 ou plus pendant trois séances, et la charge n’a pas bougé. Changer de mouvement pendant quatre semaines débloque généralement ce plateau plus vite que de s’acharner sur le même.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Données d’exemple, enregistrées uniquement dans ce navigateur. Fais-toi plaisir et modifie ce que tu veux.',
  'Full body A': 'Corps entier A',
  'Full body B': 'Corps entier B',
  'Horizontal pressing, the other half of the session.': 'Poussée horizontale, l’autre moitié de la séance.',
  'Live demo. Everything stays in this browser.': 'Démo en direct. Tout reste dans ce navigateur.',
  'No training history yet, so starting conservatively.': 'Pas encore d’historique d’entraînement, donc on commence prudemment.',
  'Passkey sign-in, sync across your devices, your own data.': 'Connexion par passkey, synchronisation entre tes appareils, tes propres données.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Remet le plan, les séances et les pesées d’exemple dans leur état de départ.',
  'Reset': 'Réinitialiser',
  'Reset demo data': 'Réinitialiser les données de démo',
  'Reset demo data?': 'Réinitialiser les données de démo ?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Revu comme demandé. Tout ce que tu n’as pas remis en question est exactement comme avant.',
  'Same pattern, higher reps than day A.': 'Même mouvement, plus de répétitions que le jour A.',
  'Self-host it in a minute →': 'Héberge-le toi-même en une minute →',
  'Self-host openGym': 'Héberger openGym soi-même',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Les séances dépassent d’environ quinze minutes. C’est l’exercice accessoire qui a le moins à perdre avec une série de moins.',
  'Start the demo': 'Lancer la démo',
  'The main lower-body driver, where most of the strength comes from.': 'Le moteur principal du bas du corps, c’est de là que vient l’essentiel de la force.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Les mêmes mouvements, d’autres variantes : assez de recoupement pour progresser, assez de différence pour rester frais.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Les deux grands mouvements du bas du corps et de poussée d’abord, tant que tu es frais.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Cette démo tourne entièrement dans ton navigateur sur des données d’exemple. Rien n’est envoyé nulle part. La connexion par passkey et la synchronisation entre tes appareils viennent avec le serveur openGym, que tu obtiens en l’hébergeant toi-même.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Trois choses à changer, et une à savoir. Tout le reste fonctionne : le squat et les tirages progressent comme prévu.',
  'Vertical pressing.': 'Poussée verticale.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Tu as déplacé cette séance au samedi trois semaines de suite. Mieux vaut que le plan le dise plutôt que tu le contournes à chaque fois.',
  'You’re in the demo': 'Tu es dans la démo',
