  'Chosen folder': 'Dossier choisi',
  'Use default folder': 'Utiliser le dossier par défaut',
  'This folder can’t be used for backups.': 'Ce dossier ne peut pas servir aux sauvegardes.',
  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym ne peut plus écrire dans « {0} », donc les copies vont de nouveau dans Documents/openGym. Choisis à nouveau le dossier pour y revenir.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym ne peut plus écrire dans le dossier choisi, donc les copies vont de nouveau dans Documents/openGym. Choisis à nouveau le dossier pour y revenir.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Me relancer quand je saute un entraînement prévu',
  'Nudge tone': 'Ton de la relance',
  'Friendly': 'Amical',
  'Guilt trip': 'Culpabilisant',
  'Drill sergeant': 'Sergent instructeur',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Une relance le soir d’un jour prévu sans séance enregistrée, entre 20:00 et 21:30. Après 3 jours manqués d’affilée, elle se tait jusqu’à ta prochaine séance.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': 'Séance notée sur un autre appareil ? Avant la relance, le téléphone vérifie auprès de ton serveur, quand il laisse l’app tourner en arrière-plan. Ouvrir l’app remet toujours tout à jour.',
  'Everything okay?': 'Tout va bien ?',
  '{0} is still waiting. What’s up?': '{0} t’attend toujours. Que se passe-t-il ?',
  'No {0} today? Even a short session tomorrow counts.': 'Pas de {0} aujourd’hui ? Même une courte séance demain compte.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Journée difficile ? {0} peut attendre. Demain est un nouveau départ.',
  'Hey, {0} didn’t happen today. All good?': 'Hé, {0} n’a pas eu lieu aujourd’hui. Tout va bien ?',
  'I miss you': 'Tu me manques',
  '{0} waited by the door all evening. For you.': '{0} t’a attendu à la porte toute la soirée. Toi.',
  'The barbell asked about you today. I didn’t know what to say.': 'La barre a demandé de tes nouvelles aujourd’hui. Je n’ai pas su quoi lui dire.',
  'Was it something I said? {0} misses you.': 'C’est quelque chose que j’ai dit ? {0} s’ennuie de toi.',
  'I saved you a spot on the bench. It’s still empty.': 'Je t’ai gardé une place sur le banc. Elle est toujours vide.',
  'Attention, recruit!': 'Garde-à-vous, recrue !',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Tes gains font leurs valises. {0} demain, sans excuses !',
  '{0} doesn’t do itself, recruit. Move it!': '{0} ne va pas se faire tout seul, recrue. Au pas de course !',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Les excuses ne soulèvent pas de poids. Présente-toi demain pour {0} !',
  'Your muscles filed a missing-person report. Show up for {0}!': 'Tes muscles ont signalé ta disparition. Présente-toi pour {0} !',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'Cette adresse répond, mais ce n’est pas un serveur openGym. Vérifie l’URL.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Cette adresse répond, mais c’est une page de connexion ou une règle du proxy qui a répondu à la place d’openGym. Laisse passer /api/ vers openGym sans modification. Voir “Phone app and CORS” dans docs/SELF_HOSTING.md.',
  'Switch sides': 'Change de côté',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Enregistre une copie datée dans « {0} » après chaque séance terminée ou routine modifiée, et garde les {1} plus récentes.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Enregistre une copie datée dans le dossier choisi après chaque séance terminée ou routine modifiée, et garde les {0} plus récentes.',
