  // --- app tour (components/Tour.jsx) ---
  "A one-minute walk around the app": "Un tour d'une minute dans l'appli",
  "A practice workout": "Un entraînement pour de faux",
  "Backups, imports and syncing with your own server.": "Sauvegardes, imports et synchro avec ton propre serveur.",
  "Body map": "Carte du corps",
  "Catch your breath": "Reprends ton souffle",
  "Done with a set? Tick it. Go on, try it.": "Série terminée ? Coche-la. Vas-y, essaie.",
  "Filter it down": "Affine",
  "Find any exercise": "Trouve n'importe quel exercice",
  "Finish line": "Ligne d'arrivée",
  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": "Terminer enregistre la séance et fait avancer tes charges. Celle-ci, d'entraînement, disparaît en douce.",
  "Finish the tour?": "Finir la visite ?",
  "Finish your workout first, then the tour is all yours.": "Termine d'abord ta séance, la visite est à toi juste après.",
  "Kilos or pounds, and the language you like best.": "Kilos ou livres, et la langue que tu préfères.",
  "Let’s go": "C'est parti",
  "Make it yours": "À ta façon",
  "Muscles at a glance": "Les muscles en un coup d'œil",
  "Narrow the list by body part, type or the equipment you have.": "Filtre la liste par partie du corps, type ou matériel dispo.",
  "No thanks": "Non merci",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "Choisis un exercice pour voir ses meilleures séries, son max estimé et sa tendance.",
  "Pointing at: {0}": "Pointe sur : {0}",
  "Practice run": "Séance d'essai",
  "Programmes and sharing": "Programmes et partage",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "Programmes, plans de départ et partage d'un plan avec un ami : tout est derrière ce bouton.",
  "Records": "Records",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Planning dit quand, Routines dit quoi. Crée les tiennes ou prends un plan de départ.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Des milliers d'exercices dans ta langue. Mets tes favoris en étoile, ils remontent en haut.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Vois quels muscles ont bossé et lesquels ont encore besoin de repos. Touche-en un pour les détails.",
  "Show me": "Montre-moi",
  "Show the tour again": "Revoir la visite",
  "Skip tour": "Passer la visite",
  "Step {0} of {1}": "Étape {0} sur {1}",
  "Swipe a set": "Glisse une série",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "Glisse une série sur le côté pour la copier ou la supprimer. Son numéro cache encore plus.",
  "The big Start button": "Le gros bouton Démarrer",
  "The little body shows what each day works, so leg day can’t hide.": "Le petit corps montre ce que chaque jour travaille, le jour des jambes ne peut pas se cacher.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "Le repos démarre tout seul. Ajoute du temps, ou passe-le si tu te sens héroïque.",
  "The ⋯ menu": "Le menu ⋯",
  "Theme, accent colour and what Home shows.": "Thème, couleur d'accent et ce que l'Accueil affiche.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Celle-ci est pour de faux, rien n'est enregistré. Chaque ligne est une série : charge, puis répétitions. Touche un chiffre pour le changer.",
  "Tick it off": "Coche-la",
  "Today at a glance": "Aujourd'hui en bref",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "La séance du jour est ici. Une touche et tu soulèves. Un jour de repos, c'est écrit, sans culpabiliser.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Entraîne-toi à jours fixes, ou fais tourner tes routines en boucle : la suivante t'attend.",
  "Want a 1-minute tour?": "Une visite d'une minute ?",
  "Week or rotation": "Semaine ou rotation",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "On te montre le meilleur sur les vrais écrans. Tu peux arrêter quand tu veux.",
  "Workout settings, layouts, notes and extra exercises hide in here.": "Réglages de séance, dispositions, notes et exercices en plus se cachent ici.",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "Séances, séries de semaines et tout ce que tu as soulevé. Ça se remplit en t'entraînant.",
  "You stopped halfway. Want to see the rest?": "Tu t'es arrêté en chemin. Voir la suite ?",
  "Your data, your backups": "Tes données, tes sauvegardes",
  "Your progress": "Tes progrès",
  "Your routines": "Tes routines",
  "You’re set": "Tu es prêt",
  // --- date picker (#809) ---
  'Previous year': 'Année précédente',
  'Next year': 'Année suivante',
  'Pick a month': 'Choisis un mois',
  'Pick a day': 'Choisis un jour',
  'With pictures': 'Avec images',
  'A small picture next to each exercise, like a plan from the gym.': 'Une petite image à côté de chaque exercice, comme un programme de la salle.',
  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Ça se passe dans l’app openGym du téléphone : Apple Health sur iPhone, Health Connect sur Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Les webhooks sont envoyés par ton propre serveur openGym, il en faut donc un. Connecte cet appareil dans Compte.",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "Les webhooks sont désactivés sur ce serveur. Ajoute INTEGRATIONS=webhook à son .env et redémarre-le.",
  "The MCP server runs next to your own openGym server and reads your data there.": "Le serveur MCP tourne à côté de ton propre serveur openGym et y lit tes données.",
  "Only what you switch on talks to anything. The rest stays out of your way.": "Seul ce que tu actives parle à quelque chose. Le reste ne te gêne pas.",
  "Could not reach your server": "Impossible de joindre ton serveur",
  "Tap to try again": "Touche pour réessayer",
  "Disconnect {0}?": "Déconnecter {0} ?",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym arrête d’écrire et de lire. Ce qui est déjà écrit peut rester comme tes données, ou partir.",
  "Works with": "Fonctionne avec",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "Pas besoin d’autre connexion : ils écrivent dans {0}, et openGym lit à partir de là.",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "Pas besoin d’autre connexion : ils écrivent dans Apple Health ou Health Connect, et l’app openGym du téléphone lit à partir de là.",
