  "Add exercises": "Ajouter des exercices",
  "Add it to the loop": "Ajoute-la à la rotation",
  "An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.": "L’historique, les records et la progression d’un exercice sont calculés à partir de tes séances. Corrige la séance et ils suivent.",
