  "Health apps": "Applis santé",
  "Here’s the pretend one. Tap it.": "Voici la séance pour de faux. Touche-la.",
  "Home shows it on its day and Start opens it. Change it any time right here.": "L’Accueil l’affiche le bon jour et Démarrer l’ouvre. Modifie-la quand tu veux, ici même.",
