  "NFC sticker for this exercise": "Autocollant NFC pour cet exercice",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "Colle-le sur ton casier, ton sac ou la porte de la salle. Un tap avec ton téléphone et c’est parti.",
  "Set up an NFC sticker": "Configurer un autocollant NFC",
  "Shows your gym membership code, ready for the scanner.": "Affiche ton code de membre, prêt pour le scanner.",
