  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "Colle-le sur la machine. Touche-le pendant une séance pour aller à {0}, ou pour l’ajouter.",
  "Sticker ready.": "Autocollant prêt.",
  "Sticker ready. Tap it with your phone to try it.": "Autocollant prêt. Touche-le avec ton téléphone pour l’essayer.",
