  "That didn’t work. Hold your phone still on the sticker and try again.": "Ça n’a pas marché. Tiens ton téléphone immobile sur l’autocollant et réessaie.",
  "This sticker can’t hold a link. Try an NTAG sticker.": "Cet autocollant ne peut pas contenir de lien. Essaie un autocollant NTAG.",
  "This sticker is for an exercise you don’t have.": "Cet autocollant est pour un exercice que tu n’as pas.",
