  "Heavy lifts get more rungs, light ones one or none.": "Les charges lourdes ont plus de paliers, les légères un ou aucun.",
  "It hurts": "Ça fait mal",
  "It hurts, it’s taken, no time, feeling great": "Douleur, occupé, pas le temps, en forme",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Ça tire, alors plus léger pour la suite. Arrête si ça fait encore mal.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Ça tire, alors tes séries restantes passent à un mouvement qui charge le même muscle sous un angle plus doux.",
  "Keep these warm-ups": "Garder ces échauffements",
  "Kept. Same warm-ups next time, scaled to your work weight.": "C’est noté. Les mêmes échauffements la prochaine fois, ajustés à ta charge de travail.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Les séries enregistrées et ta routine restent telles quelles. Le Coach n’est ni médecin ni kinésithérapeute. Si quelque chose fait mal, consulte un professionnel.",
  "Looking at your workout…": "Je regarde ta séance…",
