  "Only the warm-ups you plan yourself.": "Seulement les échauffements que tu prévois toi-même.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Montée depuis la charge de travail : plus de paliers quand c’est lourd, moins quand c’est léger.",
