  "Short on time": "Pressé",
  "Skip the rest of {0}": "Sauter la fin de {0}",
  "Something else": "Autre chose",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Squats, développés, tirages et compagnie ont une montée. Curls et élévations démarrent à froid.",
  "Straight into the work sets.": "Directement aux séries de travail.",
  "That workout is over, so these can’t be applied any more.": "Cette séance est finie, ces suggestions ne s’appliquent plus.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "L’app monte depuis ta charge de travail : plus d’échauffements quand c’est lourd, moins quand c’est léger, avec les disques de ta salle.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Le rack est pris, fais-le à la fin. Le reste de la séance n’en a pas besoin.",
  "There’s no workout running.": "Aucune séance en cours.",
