  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "Ce fichier ne peut jamais être partagé ici. Les images et animations de la bibliothèque intégrée sont sous licence.",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "Ce fichier contient encore des infos cachées, comme un lieu. Ajoute-le à nouveau dans l’app et partage la nouvelle copie.",
