  "That tip did not come through.": "Cette astuce n’est pas arrivée.",
  "The sharing text changed. Have a quick read and try again.": "Le texte de partage a changé. Relis-le vite fait et réessaie.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "C’est public pour tout le monde sur ce serveur : toute personne ayant un compte ici peut le voir, l’essayer et le copier. Ton nom et la date l’accompagnent, toujours. Ne partage que ce qui est à toi : quelque chose que tu as fait, enregistré ou que tu as le droit de transmettre. Les images et animations d’exercices de la bibliothèque intégrée sont sous licence et ne peuvent jamais être partagées. Tu peux arrêter de partager à tout moment ; les copies que d’autres ont déjà prises restent chez eux.",
