  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} t'a laissé passer, mais ce serveur n'accepte que certains groupes. Demande à la personne qui le gère de t'ajouter.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} a renvoyé quelque chose que nous n'avons pas pu vérifier, donc personne n'a été connecté. Si ça se répète, la page d'administration dit pourquoi.",
