  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Masse grasse, masse maigre, masse osseuse, eau corporelle et métabolisme de base, tels que ta balance les a enregistrés. Affichés dans Mensurations, jamais mélangés à ce que tu notes.",
