  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "Le cardio part tel qu’il était : une course, une sortie vélo, une séance de rameur. La muscu en Musculation, avec chaque série dans la description.",
  "Change server or password": "Changer de serveur ou de mot de passe",
  "Check the connection": "Tester la connexion",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Connecte Strava une seule fois depuis openGym dans un navigateur, connecté à ton serveur. Ensuite, tes séances partent depuis le serveur, peu importe l’appareil où tu les notes.",
