  "Same as the rest ({0})": "Comme les autres ({0})",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "Les secondes pour chaque partie d’une répétition : descente, pause, montée, contraction. 3-1-1-0, c’est trois en descente, une en bas, une en montée, et direct la suivante.",
  "Show finished workouts too": "Afficher aussi les séances terminées",
  "Strava connected. Your next workout goes up by itself.": "Strava connecté. Ta prochaine séance part toute seule.",
  "Strava disconnected": "Strava déconnecté",
  "Strava is listening": "Strava est à l’écoute",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "Strava est désactivé sur ce serveur. Enregistre une app API Strava, ajoute strava à INTEGRATIONS et ses STRAVA_CLIENT_ID et STRAVA_CLIENT_SECRET au .env, puis redémarre.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Les envois vers Strava partent de ton propre serveur openGym, il en faut donc un. Connecte cet appareil à ton serveur dans Compte.",
  "Strength workouts too": "Les séances de muscu aussi",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "Abonne-toi à ce lien dans ton app de calendrier. Toute personne qui l’a voit ton plan, alors garde-le pour toi.",
  "Tempo": "Tempo",
  "Tempo for this set": "Tempo pour cette série",
  "Tempo {0}": "Tempo {0}",
  "Tempo {0}, start the guide": "Tempo {0}, lancer le guide",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "Le lien de calendrier est fourni par ton propre serveur openGym, il en faut donc un. Connecte cet appareil à ton serveur dans Compte.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "Le lien cesse de marcher tout de suite. Ce que ton calendrier affiche déjà peut rester jusqu’à sa prochaine actualisation.",
  "The old link stops working, and every calendar that uses it needs the new one.": "L’ancien lien cesse de marcher, et chaque calendrier qui l’utilise aura besoin du nouveau.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "Le mot de passe reste sur cet appareil, dans son stockage sécurisé. Il n’est jamais synchronisé ni mis dans une sauvegarde.",
  "The server cannot show this link again. Make a new one.": "Le serveur ne peut plus afficher ce lien. Crées-en un nouveau.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "Cet appareil arrête de sauvegarder et oublie le mot de passe. Les sauvegardes déjà dans le dossier y restent.",
  "Tick the set": "Valider la série",
  "Turn off": "Désactiver",
  "Turn off the calendar feed?": "Désactiver le flux de calendrier ?",
  "Up as fast as you can. The guide gives it one quick second.": "Monte aussi vite que tu peux. Le guide lui donne une petite seconde.",
  "Uploading": "Envoi en cours",
  "User name": "Nom d’utilisateur",
