  "When the app is open, at most once a day, on this device.": "Quand l’app est ouverte, une fois par jour au plus, sur cet appareil.",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "Tes séances prévues dans Apple Calendar, Google Calendar ou Outlook, toujours à jour. Un lien privé que seul ton calendrier connaît.",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "Ton serveur oublie la connexion et arrête les envois. Ce qui est sur Strava y reste, et l’app Strava garde son accès jusqu’à ce que tu le retires sur strava.com.",
