  "The server did not take that name and password. An app password usually works best.": "Le serveur n’a pas accepté ce nom et ce mot de passe. Un mot de passe d’application marche souvent mieux.",
  "That folder is not there, and openGym could not make it. Make it on the server first.": "Ce dossier n’existe pas, et openGym n’a pas pu le créer. Crée-le d’abord sur le serveur.",
  "The server says this account may not write there.": "Le serveur dit que ce compte n’a pas le droit d’écrire ici.",
