  // --- promises-146: progression rules, shoulder heads and lats, bench, own media ---,
  "Steady double progression": "Double progression régulière",
  "Undulating days": "Jours ondulés",
  "Shorter rests": "Repos plus courts",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Monte dans une fourchette de répétitions, une à la fois. Chaque série doit atteindre l’objectif avant qu’il bouge, et en haut de la fourchette la charge augmente.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Chaque séance tourne : un jour moyen à tes répétitions, un jour lourd avec moins, un jour léger avec plus. Les charges viennent de ton max estimé, donc elles montent quand tu progresses.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Même charge, un peu moins de repos chaque fois que toutes les séries sont propres. Au repos le plus court, la charge augmente et le repos repart de zéro.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Chaque série a fait {0}. Même charge, {1} répétitions cette fois.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Toutes les séries n’ont pas encore atteint {0}. Même charge et même objectif ({1} sur {2} restants).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Toutes les séries propres. Même charge avec {0} s de repos en moins : {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Propre au repos le plus court. {0} {1} d’aide en moins, repos de retour à {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Propre au repos le plus court. {0} {1} de plus, repos de retour à {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Bloqué depuis {0} séances. Même charge avec plus de repos : {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Répétitions manquées la dernière fois. Même charge et même repos ({0} sur {1} restants).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Jour lourd : {0} répétitions à {1} {2}, d’après ton max estimé de {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Jour léger : {0} répétitions à {1} {2}, d’après ton max estimé de {3} {2}.",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Jour moyen : {0} répétitions à {1} {2}, d’après ton max estimé de {3} {2}.",
