  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Quatre touches sur le sommeil, l’énergie, les courbatures et le stress. Les jours difficiles, openGym propose d’alléger, et après quelques semaines tu vois ce que tes bons jours ont en commun.",
