  "{1} is still recovering, so it sits this one out.": "{1} est encore en récupération, il fait une pause cette fois.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "Et ça ne bougera pas : openGym Offline n’a pas la permission Internet, Android bloque donc tout ce qu’il pourrait tenter.",
  "Any of the sounds on your phone.": "N’importe quel son de ton téléphone.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Fais une sauvegarde de temps en temps dans Réglages, Données et sauvegarde. Un fichier sur ton téléphone est la seule copie qui existe.",
  "Closing the app resets the count; the log never leaves the phone.": "Fermer l’app remet le compteur à zéro ; le journal ne quitte jamais le téléphone.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Compté depuis {0}, au démarrage de l’app. La fermer le remet à zéro ; le journal ne quitte jamais le téléphone.",
  "Each reminder can sound different, so you know which one it is before you look.": "Chaque rappel peut avoir son propre son, pour savoir lequel c’est avant même de regarder.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Tout ce que cette app a demandé à Internet, le plus récent en premier. L’adresse seulement, jamais le contenu.",
  "For reading mid-set without your glasses.": "Pour lire en pleine série, sans lunettes.",
  "Larger": "Plus grand",
  "Last at {0}": "Dernière à {0}",
  "Latest": "Récent",
  "Less: no sliding, bouncing or snow. Things just appear.": "Moins : rien ne glisse, ne rebondit ni ne neige. Tout apparaît, simplement.",
  "Like the phone": "Comme le téléphone",
  "Mostly your own server, {0}, when there was something to sync.": "Surtout ton propre serveur, {0}, quand il y avait quelque chose à synchroniser.",
  "Motion": "Mouvement",
  "Network log": "Journal réseau",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "Pas de recherche sur carte dans openGym Offline. Mets-toi dans ta salle, touche Position actuelle, c’est fait.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Pas un seul octet n’a quitté ce téléphone. Ton entraînement ne regarde que toi.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Rien pour l’instant. Ton serveur a des nouvelles de ce téléphone quand il y a quelque chose à synchroniser.",
  "Phone default": "Son par défaut du téléphone",
