  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "Voici openGym Offline : Android ne le laisse même pas aller sur Internet. Envie de synchro ? L’app openGym normale sait faire, juste à côté.",
