  // --- TestFlight feedback 11-08: share card colours, set colour tags, band levels, voice files ---
  "A see-through PNG: only the type, the tiles and the logo. Lay it over anything.": "Un PNG transparent : juste le texte, les tuiles et le logo. À poser sur ce que tu veux.",
  "Background": "Fond",
  "Colour tag": "Couleur de la série",
  "Colour tag: {0}": "Couleur de la série : {0}",
  "Custom colour for {0}": "Couleur personnalisée pour {0}",
